/**
 * Fichier : controle.js
 * Épreuve Pratique Bac STI - Contrôle de Saisie Officiel
 */
function verif() {
  let cin = document.getElementById("cin").value.trim();
  let nom = document.getElementById("nom").value.trim();
  let genreM = document.getElementById("genreM");
  let genreF = document.getElementById("genreF");
  let section = document.getElementById("section");

  // Règle 1 : CIN composé de 8 chiffres
  if (cin.length !== 8 || isNaN(cin)) {
    alert("Erreur : Le numéro de CIN doit comporter exactement 8 chiffres décimaux !");
    document.getElementById("cin").focus();
    return false;
  }

  // Règle 2 : Nom et prénom non vides
  if (nom === "") {
    alert("Erreur : Veuillez renseigner le nom et prénom !");
    document.getElementById("nom").focus();
    return false;
  }

  // Règle 3 : Genre sélectionné
  if (!genreM.checked && !genreF.checked) {
    alert("Erreur : Veuillez sélectionner le genre (Masculin / Féminin) !");
    return false;
  }

  // Règle 4 : Sélection effective dans la liste
  if (section.selectedIndex === 0 || section.value === "") {
    alert("Erreur : Veuillez sélectionner une section dans la liste !");
    section.focus();
    return false;
  }

  // Toutes les conditions sont remplies : validation du formulaire
  return true;
}

function formater(ch) {
  ch = ch.trim();                      // retire les espaces aux extrémités
  if (ch.length > 0) {
    ch = ch.toLowerCase();             // "bravo"
    ch = ch.replace(ch.charAt(0), ch.charAt(0).toUpperCase()); // "Bravo"
  }
  return ch;
}
